function solve(text) {
  const match = { ")": "(", "]": "[", "}": "{" };
  const pile = [];
  for (const mark of text) {
    if (mark === "(" || mark === "[" || mark === "{") pile.push(mark);
    else if (pile.pop() !== match[mark]) return false;
  }
  return pile.length === 0;
}

