function solve(n) {
  if (n <= 2) return n;
  let oneStepBack = 1;
  let twoStepsBack = 2;
  for (let step = 3; step <= n; step++) {
    const here = oneStepBack + twoStepsBack;
    oneStepBack = twoStepsBack;
    twoStepsBack = here;
  }
  return twoStepsBack;
}

