approach:
function solve(text) {
  let best = 0;
  let start = 0;
  const last = new Map();
  for (let i = 0; i < text.length; i++) {
    const previous = last.get(text[i]);
    if (previous !== undefined && previous >= start) start = previous + 1;
    last.set(text[i], i);
    best = Math.max(best, i - start + 1);
  }
  return best;
}

